 import { supabase } from '../lib/supabase';

const YOCO_PUBLIC_KEY = process.env.REACT_APP_YOCO_PUBLIC_KEY;

export async function initiatePayment({
  amount,
  currency = 'ZAR',
  email,
  fullName,
  userId,
  communityId = null,
  type = 'community',
  metadata = {}
}) {
  try {
    // 1. Calculate fees
    const platformFee = type === 'community' ? amount * 0.30 : amount * 0.10;
    const creatorEarnings = type === 'community' ? amount * 0.70 : amount * 0.90;

    // 2. Create pending record in Supabase
    const { data: payment, error } = await supabase
      .from('subscription_payments')
      .insert({
        user_id: userId,
        community_id: communityId,
        amount: amount,
        currency: currency,
        platform_fee: platformFee,
        creator_earnings: creatorEarnings,
        type: type,
        status: 'pending'
      })
      .select()
      .single();

    if (error) throw error;

    // 3. Check if Yoco SDK is loaded
    if (typeof window.Yoco === 'undefined') {
      throw new Error('Yoco SDK not loaded. Please refresh the page and try again.');
    }

    // 4. Initialize Yoco
    const yoco = new window.Yoco({
      key: YOCO_PUBLIC_KEY
    });

    // 5. Open the popup
    yoco.checkout({
      amount: Math.round(amount * 100), // Yoco expects cents
      currency: currency,
      customer: {
        email: email,
        fullName: fullName || email
      },
      metadata: {
        payment_id: payment.id,
        user_id: userId,
        community_id: communityId,
        type: type,
        ...metadata
      },
      onSuccess: async (result) => {
        console.log('Yoco Payment Successful:', result);
        window.location.href = `/payment/success?payment_id=${payment.id}`;
      },
      onClose: () => {
        console.log('Yoco Payment Modal Closed');
      }
    });

    return { success: true, paymentId: payment.id };

  } catch (error) {
    console.error('Yoco payment error:', error);
    return { success: false, error: error.message };
  }
}
